/* a MESMA conta do motor_bonus.nota_da_medida: -2 a +2 */
function notaDaMedida(v,k){ if(v<=k[0])return -2; if(v<=k[1])return -1;
 if(v<=k[2])return 0; if(v<=k[3])return 1; return 2; }
/* as 12 linhas do corpo de um card numa funcao, no formato do frows:
   [nome, peso, alvo, valor, nota, direcao, pontos] */
function corpoLinhas(c){
 try{
  var base=String(c.id).split("@")[0];
  var v=CORPO_MOTOR[base], M=CORPO_MOLDE[c.tipo];
  if(!v||!M) return [];
  var out=[],i,m,e,val,n,pts;
  for(i=0;i<CORPO_ORDEM.length;i++){
   m=CORPO_ORDEM[i]; e=M.m[m]; val=v[i];
   if(!e||typeof val!=="number") continue;
   n=notaDaMedida(val,e[3]); pts=n*e[0]*e[1];
   out.push([m, e[0]?e[1]:0, e[2], val, n, e[0],
             Math.round(pts*100)/100]);
  }
  return out;
 }catch(e){ return []; }
}
window.corpoLinhas=corpoLinhas;
/* ⛔ 19/08 — O BANCO MANDA. A TELA NAO CALCULA BONUS.
   Ordem do Luis, 19/08: *"a gente alterou a fonte de dados que estava
   dispersa para uma unica fonte. Se o banco fala que o bonus e x, o
   bonus e x."*
   Antes havia uma "rede de seguranca": quando a chave nao era achada,
   a tela CALCULAVA sozinha. Isso criou dois enderecos para o mesmo
   numero — e a sessao do encaixe mediu a conta disso: 1.567 linhas
   divergindo no estilo da IA e 250 no corpo, com a NOTA usando um
   valor e o TEXTO ao lado mostrando outro.
   Agora a rede sai. Sem o numero do banco o bonus e ZERO para a conta
   e fica REGISTRADO como falta — nao como medida. E a mesma regra do
   Luis de 15/08: nao se inventa zero no lugar de nao sei.
   Quem quiser ver quanto ficou sem: window.BONUS_SEM_BANCO. */
window.BONUS_SEM_BANCO={n:0,chaves:{}};
function bonusPronto(c,i,calcula){
 try{ var k=String(c.id).split("@")[0]+"|"+c.tipo;
  var b=BONUS_PRONTO[k];
  if(b && typeof b[i]==="number") return b[i];
  if(!BONUS_SEM_BANCO.chaves[k]){ BONUS_SEM_BANCO.chaves[k]=1;
                                  BONUS_SEM_BANCO.n++; }
 }catch(e){}
 return 0;
}


